let _lang = localStorage.getItem('iceample:lang') || 'en'

export function t(key) {
  return LANGS[_lang]?.[key] ?? LANGS['en']?.[key] ?? key
}

export function getLang() { return _lang }

export function setLang(lang) {
  if (!LANGS[lang]) return
  _lang = lang
  localStorage.setItem('iceample:lang', lang)
  applyTranslations()
}

/** Apply text direction (RTL for Arabic, LTR otherwise) + lang attribute. */
export function applyDirection() {
  const rtl = RTL_LANGS.includes(_lang)
  document.documentElement.dir  = rtl ? 'rtl' : 'ltr'
  document.documentElement.lang = _lang
}

// Reverse index (any language's value → key) so we can recover the i18n key of
// a title/label that was baked in another language, then re-translate it.
let _reverse = null
function reverseMap() {
  if (_reverse) return _reverse
  _reverse = new Map()
  // English first so it wins ties deterministically, then the rest.
  const order = ['en', ...Object.keys(LANGS).filter(l => l !== 'en')]
  for (const lang of order) {
    const dict = LANGS[lang]; if (!dict) continue
    for (const k in dict) {
      const v = dict[k]
      if (typeof v === 'string' && v && !_reverse.has(v)) _reverse.set(v, k)
    }
  }
  return _reverse
}

/** Set a translatable tooltip and remember its key for future re-translation. */
export function setTitle(el, key) {
  if (!el) return
  el.dataset.i18nTitle = key
  el.title = t(key)
}

export function applyTranslations() {
  applyDirection()
  const rev = reverseMap()

  document.querySelectorAll('[data-i18n]').forEach(el => {
    el.textContent = t(el.dataset.i18n)
  })

  document.querySelectorAll('[data-i18n-placeholder]').forEach(el => {
    el.placeholder = t(el.dataset.i18nPlaceholder)
  })

  // Tooltips already tagged with their key.
  document.querySelectorAll('[data-i18n-title]').forEach(el => {
    el.title = t(el.dataset.i18nTitle)
  })

  // Untagged tooltips: recover the key by reverse lookup, tag, translate.
  document.querySelectorAll('[title]:not([data-i18n-title])').forEach(el => {
    const k = rev.get(el.getAttribute('title'))
    if (k) { el.dataset.i18nTitle = k; el.title = t(k) }
  })

  // Tooltips stashed by the annotations toggle (title removed → data-hint).
  document.querySelectorAll('[data-hint]:not([data-i18n-title])').forEach(el => {
    const k = rev.get(el.getAttribute('data-hint'))
    if (k) { el.dataset.i18nTitle = k; el.setAttribute('data-hint', t(k)) }
  })

  // Floating tool-window titles (tracked and ad-hoc).
  document.querySelectorAll('.tool-win-title:not([data-i18n])').forEach(el => {
    const k = rev.get(el.textContent.trim())
    if (k) { el.dataset.i18n = k; el.textContent = t(k) }
  })
}
